// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter - balanceBefore, amount);
    }
}
